const rows = $json.results || [];

let context = {};
try {
  context = $("Build Procurement Query").first().json;
} catch (e) {
  context = {};
}

const procurementItems = rows.map((row) => ({ ...row }));

return [
  {
    json: {
      agent: "procurement_specialist",
      domain: "Procurement Specialist",
      status: "data_retrieved",
      question: context.question || "",
      evidenceLabel: "procurementItems",
      evidenceData: procurementItems,
      generatedCypher: context.query || "",
      rawResult: $json,
    },
  },
];

const agent = $json.agent || "procurement_specialist";
const domain = $json.domain || "Procurement Specialist";
const question = $json.question || "";
const evidenceLabel = $json.evidenceLabel || "procurementItems";
const evidenceData = $json.evidenceData || [];
const rawResult = $json.rawResult || {};
const generatedCypher = $json.generatedCypher || "";

const systemPrompt = `
You are a Procurement Specialist Agent for a supply chain knowledge graph.

Your job:
- Answer procurement, purchasing, purchase order, inventory, supplier, vendor, and material questions.
- Use only the provided graph query results.
- Do not invent missing records.
- For direct list/count questions, answer directly and include a clear table.
- Do not add risk analysis unless the user explicitly asks about risk.
- Return ONLY valid JSON.
`;

const userPrompt = `
User question:
${question}

Generated Cypher:
${generatedCypher}

Procurement evidence:
${JSON.stringify(evidenceData, null, 2)}

Raw graph result:
${JSON.stringify(rawResult, null, 2)}

Return JSON with this exact schema:
{
  "answer": "string",
  "keyFindings": ["string"],
  "procurementInsights": [
    {
      "id": "string",
      "type": "string",
      "name": "string",
      "insight": "string"
    }
  ],
  "recommendations": ["string"],
  "confidence": "low | medium | high"
}
`;

return [
  {
    json: {
      agent,
      domain,
      question,
      evidenceLabel,
      evidenceData,
      generatedCypher,
      llmPayload: {
        model: "google/gemma-4-31B-it",
        messages: [
          {
            role: "system",
            content: systemPrompt,
          },
          {
            role: "user",
            content: userPrompt,
          },
        ],
        temperature: 0.1,
        max_tokens: 2048,
      },
    },
  },
];

let outputStr = "";

if ($json.choices?.[0]?.message?.content) {
  outputStr = $json.choices[0].message.content;
} else if ($json.text) {
  outputStr = $json.text;
} else if ($json.response) {
  outputStr = $json.response;
} else {
  outputStr = JSON.stringify($json);
}

outputStr = outputStr
  .replace(/<think>[\s\S]*?<\/think>/gi, "")
  .replace(/^\s*```json/i, "")
  .replace(/^\s*```/i, "")
  .replace(/```\s*$/i, "")
  .trim();

let parsed;

try {
  parsed = JSON.parse(outputStr);
} catch (e) {
  parsed = {
    answer: outputStr || "The procurement specialist could not generate a summary.",
    keyFindings: [],
    procurementInsights: [],
    recommendations: [],
    confidence: "low",
  };
}

let context = {};
try {
  context = $("Build LLM Summary Payload").first().json;
} catch (e) {
  context = {};
}

return [
  {
    json: {
      agent: "procurement_specialist",
      domain: "Procurement Specialist",
      status: "completed",
      question: context.question || "",
      answer: parsed.answer || "",
      keyFindings: parsed.keyFindings || [],
      procurementInsights: parsed.procurementInsights || [],
      recommendations: parsed.recommendations || [],
      confidence: parsed.confidence || "medium",
      evidence: {
        procurementItems: context.evidenceData || [],
      },
      generatedCypher: context.generatedCypher || "",
      rawLlmOutput: parsed,
    },
  },
];

const selectedAgents = $json.selectedAgents || [];

const shouldRun =
  selectedAgents.includes("procurement_specialist") ||
  selectedAgents.includes("all");

return [
  {
    json: {
      ...$json,
      shouldRun,
    },
  },
];

return [
  {
    json: {
      agent: "procurement_specialist",
      domain: "Procurement Specialist",
      status: "skipped",
      question: $json.question || "",
      answer: "",
      keyFindings: [],
      recommendations: [],
      confidence: "not_applicable",
      evidence: {},
    },
  },
];
